"""Resolve dbt models from a manifest generated by a DuckDB project."""

from __future__ import annotations

import json
import subprocess
from dataclasses import dataclass
from pathlib import Path

COMMENT_MARKER = "<!-- diffscope:dbt -->"


@dataclass(frozen=True)
class Model:
    name: str
    alias: str
    database: str | None
    keys: list[str]

    def relation(self, catalog: str, schema: str) -> str:
        return ".".join(
            '"' + part.replace('"', '""') + '"' for part in (catalog, schema, self.alias)
        )


def load_models(project_dir: Path, names: list[str], keys: list[str] | None) -> list[Model]:
    path = project_dir.expanduser() / "target" / "manifest.json"
    try:
        manifest = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"DBT manifest is missing at {path}. Run dbt build first.") from exc
    except json.JSONDecodeError as exc:
        raise ValueError(f"Could not read DBT manifest at {path}: {exc.msg}") from exc
    adapter = manifest.get("metadata", {}).get("adapter_type")
    if adapter is not None and adapter != "duckdb":
        raise ValueError(f"Expected a DuckDB manifest, got adapter {adapter!r}")

    nodes = {
        node_id: node
        for node_id, node in manifest.get("nodes", {}).items()
        if node.get("resource_type") == "model"
    }
    models = []
    for name in names:
        matches = (
            [name]
            if name in nodes
            else [node_id for node_id, node in nodes.items() if node["name"] == name]
        )
        if not matches:
            raise ValueError(f"Model {name!r} was not found in {path}")
        if len(matches) > 1:
            raise ValueError(
                f"Model {name!r} is ambiguous. Use one of: {', '.join(sorted(matches))}"
            )

        node = nodes[matches[0]]
        config = node.get("config", {})
        if config.get("materialized") == "ephemeral":
            raise ValueError(f"Ephemeral model {name!r} has no relation to compare")
        model_keys = keys
        if model_keys is None:
            meta = (node.get("meta") or {}) | (config.get("meta") or {})
            model_keys = meta.get("diffscope_keys")
        if (
            not isinstance(model_keys, list)
            or not model_keys
            or any(not isinstance(key, str) or not key.strip() for key in model_keys)
        ):
            raise ValueError(f"Model {name!r} needs keys. Pass --key or set meta.diffscope_keys.")
        models.append(
            Model(name, node.get("alias") or node["name"], node.get("database"), model_keys)
        )
    return models


def post_pr_comment(report: str, repository: str, pr_number: str) -> None:
    """Create or update the workflow bot's diff comment using gh."""
    body = f"{COMMENT_MARKER}\n{Path(report).read_text(encoding='utf-8')}"
    endpoint = f"repos/{repository}/issues/{pr_number}/comments"
    response = subprocess.run(
        ["gh", "api", endpoint, "--paginate", "--slurp"],
        check=True,
        stdout=subprocess.PIPE,
        text=True,
    )
    comment_id = next(
        (
            comment["id"]
            for page in json.loads(response.stdout)
            for comment in page
            if (comment.get("user") or {}).get("login") == "github-actions[bot]"
            and (comment.get("body") or "").partition("\n")[0] == COMMENT_MARKER
        ),
        None,
    )
    method = "POST"
    if comment_id is not None:
        method = "PATCH"
        endpoint = f"repos/{repository}/issues/comments/{comment_id}"
    subprocess.run(
        ["gh", "api", endpoint, "--method", method, "--input", "-", "--silent"],
        input=json.dumps({"body": body}),
        check=True,
        text=True,
    )
